using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using PowerliftingSimulator.Athlete;
using PowerliftingSimulator.Bench.Unity;
using PowerliftingSimulator.Equipment;
using PowerliftingSimulator.Foundation;
using UnityEngine;

namespace PowerliftingSimulator.Deadlift.Unity
{
    /// <summary>
    /// GAM-70: the versioned, offline-generated close-bar reference family.
    ///
    /// Two prepared references are generated by the full closed-chain solver on
    /// the actual athlete model, from the measured plant of a qualified attempt:
    /// the ascent through knee passage (anchored at bar separation) and the
    /// post-knee continuation into the suspended close-bar endpoint (anchored at
    /// knee passage). The artifact stores each anchor state, every solved key and
    /// the endpoint sample, bit-exact (IEEE-754 bit patterns), together with a
    /// fingerprint of the declared model inputs it was generated for.
    ///
    /// The runtime never regenerates these trajectories. It validates the
    /// artifact while the attempt is being prepared (fingerprint, then the
    /// recorded references re-checked against the same closure and clearance
    /// contracts the generator enforced) and, at each physical event, admits the
    /// measured state through <see cref="DeadliftReferenceAdmission"/>.
    /// </summary>
    public sealed class DeadliftCloseBarReference
    {
        /// <summary>Bump when the reference objective, its sampling or its admission contract changes.</summary>
        public const string ContractVersion = "GAM-70/close-bar-reference/v1";
        public const string ResourcePath = "Deadlift/GAM70CloseBarReference";
        public const string AssetPath = "Assets/Resources/Deadlift/GAM70CloseBarReference.json";

        public sealed class Plan
        {
            public DeadliftPreparedAscentPlan.Anchor State;
            public List<(Pose Root, Pose Bar, Dictionary<string, Quaternion> Logical)> Keys =
                new List<(Pose Root, Pose Bar, Dictionary<string, Quaternion> Logical)>();
            /// <summary>Endpoint sample of a continuation (null for the ascent prefix).</summary>
            public DeadliftPreparedAscentPlan.Sample Lockout;
            public float MinGapM, SweptGapM, ClosureM, ClosureDeg;
        }

        public string Contract = ContractVersion;
        public string Fingerprint;
        public string Generator;
        public string[] JointIds;
        public Plan Prefix;
        public Plan PostKnee;
        /// <summary>The stock qualified lift path the prepared references are built on (state independent).</summary>
        public DeadliftLiftPath.Snapshot StockPath;

        public static Plan Record(DeadliftPreparedAscentPlan plan)
        {
            var record = new Plan { State = plan.State, Lockout = plan.Lockout };
            for (int i = 0; i < plan.KeyCount; i++)
            {
                DeadliftPreparedAscentPlan.Sample key = plan.Key(i);
                record.Keys.Add((key.Root, key.Bar, new Dictionary<string, Quaternion>(key.Logical)));
            }
            var check = plan.MeasureInterpolation();
            record.MinGapM = check.MinGap;
            record.SweptGapM = check.SweptGap;
            record.ClosureM = check.PositionError;
            record.ClosureDeg = check.RotationError;
            return record;
        }

        // ---------------- Fingerprint of the declared model inputs ----------------

        /// <summary>
        /// Hash of every declared input the references depend on: tick and solver
        /// substeps, segment masses, mass properties, collision geometry and
        /// friction, joint topology, frames, limits and drive ceilings, the ankle
        /// roll DOF, the bar load and shaft, the qualified B2 setup vector and
        /// stance/grip specification, and the reference contract version.
        /// </summary>
        public static string ComputeFingerprint(PhysicalAthleteRig rig, Rigidbody bar) => ComputeFingerprint(rig, bar, out _);

        public static string ComputeFingerprint(PhysicalAthleteRig rig, Rigidbody bar, out string source)
        {
            var b = new StringBuilder();
            void F(float v) => b.Append(v.ToString("G9", CultureInfo.InvariantCulture)).Append(',');
            void V(Vector3 v) { F(v.x); F(v.y); F(v.z); }
            void Q(Quaternion q) { F(q.x); F(q.y); F(q.z); F(q.w); }
            void Material(Collider c)
            {
                PhysicsMaterial m = c.sharedMaterial;
                if (m == null) { b.Append("default-material,"); return; }
                F(m.staticFriction); F(m.dynamicFriction); F(m.bounciness);
                b.Append(m.frictionCombine).Append(',').Append(m.bounceCombine).Append(',');
            }
            void Geometry(Collider c)
            {
                switch (c)
                {
                    case CapsuleCollider k: b.Append("capsule,"); F(k.radius); F(k.height); b.Append(k.direction).Append(','); V(k.center); break;
                    case BoxCollider k: b.Append("box,"); V(k.size); V(k.center); break;
                    case SphereCollider k: b.Append("sphere,"); F(k.radius); V(k.center); break;
                    default: b.Append(c.GetType().Name).Append(','); break;
                }
                Material(c);
            }

            b.Append(ContractVersion).Append('|').Append(PhysicalAthleteDefinition.ProfileId).Append('|');
            b.Append(SimulationConstants.FixedDeltaTimeSeconds.ToString("R", CultureInfo.InvariantCulture)).Append(',')
                .Append(SimulationConstants.PhysicsSubstepsPerTick).Append('|');
            foreach (PhysicalSegmentRecipe recipe in PhysicalAthleteDefinition.Segments)
            {
                PhysicalAthleteRig.SegmentRuntime segment = rig.Segments[recipe.Id];
                b.Append(recipe.Id).Append(':').Append(recipe.ParentId).Append(',');
                F(segment.Body.mass); V(segment.Body.centerOfMass); V(segment.Body.inertiaTensor); Q(segment.Body.inertiaTensorRotation);
                Geometry(segment.Collider);
                b.Append('|');
            }
            BenchKinematics kinematics = new BenchKinematics(rig);
            foreach (PoweredJointController.PoweredJointRuntime joint in rig.PoweredController.Joints)
            {
                BenchKinematics.JointInfo info = kinematics.Joint(joint.Id);
                b.Append(joint.Id).Append(':').Append(joint.Recipe.Family).Append(',').Append(joint.Recipe.Kind).Append(',');
                F(joint.Recipe.LowDegrees); F(joint.Recipe.HighDegrees); F(joint.Recipe.SecondaryLimitDegrees);
                V(info.Anchor); V(info.ConnectedAnchor); Q(info.NeutralParentToChild); Q(info.JointSpace);
                ConfigurableJoint cj = joint.Joint;
                b.Append(cj.angularXMotion).Append(',').Append(cj.angularYMotion).Append(',').Append(cj.angularZMotion).Append(',');
                F(cj.lowAngularXLimit.limit); F(cj.highAngularXLimit.limit); F(cj.angularYLimit.limit); F(cj.angularZLimit.limit);
                // Declared actuator capacity and servo (the drive ceilings follow activation at run time).
                foreach (JointFamilyProfile? profile in new[] { joint.Profile, joint.SecondaryProfile })
                {
                    if (!profile.HasValue) { b.Append("unpowered,"); continue; }
                    b.Append(profile.Value.Id).Append(',');
                    F(profile.Value.Spring); F(profile.Value.Damper); F(profile.Value.BaseCapacityNm); F(profile.Value.MaxTargetRateRadS);
                }
                b.Append('|');
            }
            F(DeadliftAnkleRoll.LimitDegrees);
            Geometry(rig.PlatformCollider);
            b.Append("bar,");
            F(bar.mass); V(bar.centerOfMass); V(bar.inertiaTensor);
            foreach (Collider c in bar.GetComponentsInChildren<Collider>(true).OrderBy(c => c.name, StringComparer.Ordinal).ThenBy(c => c.GetType().Name, StringComparer.Ordinal))
            {
                b.Append(c.name).Append(':');
                Geometry(c);
            }
            b.Append('|').Append("B2,");
            foreach (double x in DeadliftQualifiedSetup.B2)
                b.Append(x.ToString("R", CultureInfo.InvariantCulture)).Append(',');
            DeadliftSetupSpec spec = DeadliftQualifiedSetup.SumoPronated();
            b.Append('|').Append(spec.Label).Append(',');
            F(spec.BarAxisY); F(spec.BarZ); F(spec.BarRadius); F(spec.StanceHalfWidth); F(spec.ToeOutDeg); F(spec.GripHalfWidth);
            F(spec.BarMassKg); F(DeadliftQualifiedSetup.BarKg);
            b.Append(spec.Grip).Append(',').Append(spec.Technique).Append(',').Append(spec.Support);

            source = b.ToString();
            using (SHA256 sha = SHA256.Create())
                return string.Concat(sha.ComputeHash(Encoding.UTF8.GetBytes(source)).Select(x => x.ToString("x2")));
        }

        // ---------------- Bit-exact serialization ----------------

        [Serializable]
        private sealed class PlanDto
        {
            public int keyCount;
            public int[] anchor;
            public int[] keys;
            public int[] lockout;
            public float minGapM, sweptGapM, closureM, closureDeg;
        }

        [Serializable]
        private sealed class PathDto
        {
            public int keyCount, parameterCount;
            public long[] x, cost, hard;
            public int[] rise, lambda, flags, scalars;
        }

        [Serializable]
        private sealed class Dto
        {
            public string contract;
            public string fingerprint;
            public string generator;
            public string[] jointIds;
            public PlanDto prefix;
            public PlanDto postKnee;
            public PathDto stockPath;
        }

        public string ToJson()
        {
            var dto = new Dto
            {
                contract = Contract, fingerprint = Fingerprint, generator = Generator, jointIds = JointIds,
                prefix = Write(Prefix), postKnee = Write(PostKnee), stockPath = Write(StockPath)
            };
            return JsonUtility.ToJson(dto, false);
        }

        public static DeadliftCloseBarReference FromJson(string json)
        {
            Dto dto = JsonUtility.FromJson<Dto>(json);
            if (dto == null || dto.jointIds == null || dto.prefix == null || dto.postKnee == null)
                throw new FormatException("The close-bar reference artifact is incomplete.");
            var reference = new DeadliftCloseBarReference
            {
                Contract = dto.contract, Fingerprint = dto.fingerprint, Generator = dto.generator, JointIds = dto.jointIds
            };
            reference.Prefix = Read(dto.prefix, dto.jointIds, false);
            reference.PostKnee = Read(dto.postKnee, dto.jointIds, true);
            reference.StockPath = Read(dto.stockPath);
            return reference;
        }

        public static DeadliftCloseBarReference LoadResource(out string failure)
        {
            failure = null;
            TextAsset asset = Resources.Load<TextAsset>(ResourcePath);
            if (asset == null)
            {
                failure = $"No close-bar reference artifact at Resources/{ResourcePath}.";
                return null;
            }
            try
            {
                return FromJson(asset.text);
            }
            catch (Exception e)
            {
                failure = "The close-bar reference artifact could not be read: " + e.Message;
                return null;
            }
        }

        private PlanDto Write(Plan plan)
        {
            var anchor = new List<int>();
            DeadliftPreparedAscentPlan.Anchor s = plan.State;
            Put(anchor, s.Root); Put(anchor, s.Bar); Put(anchor, s.Feet[0]); Put(anchor, s.Feet[1]);
            Put(anchor, s.GripRotations[0]); Put(anchor, s.GripRotations[1]);
            if (!s.JointIds.SequenceEqual(JointIds))
                throw new InvalidOperationException("Anchor joints differ from the artifact joint order.");
            foreach (Quaternion q in s.Measured)
                Put(anchor, q);
            Put(anchor, s.StartProgress); Put(anchor, s.LiftRate); Put(anchor, s.BarTangent);

            var keys = new List<int>();
            foreach (var key in plan.Keys)
            {
                Put(keys, key.Root); Put(keys, key.Bar);
                foreach (string id in JointIds)
                    Put(keys, key.Logical[id]);
            }
            var lockout = new List<int>();
            if (plan.Lockout != null)
            {
                Put(lockout, plan.Lockout.Root); Put(lockout, plan.Lockout.Bar);
                foreach (string id in JointIds)
                    Put(lockout, plan.Lockout.Logical[id]);
            }
            return new PlanDto
            {
                keyCount = plan.Keys.Count, anchor = anchor.ToArray(), keys = keys.ToArray(), lockout = lockout.ToArray(),
                minGapM = plan.MinGapM, sweptGapM = plan.SweptGapM, closureM = plan.ClosureM, closureDeg = plan.ClosureDeg
            };
        }

        private static Plan Read(PlanDto dto, string[] jointIds, bool continuation)
        {
            int j = jointIds.Length;
            int anchorLength = 7 * 4 + 4 * 2 + 4 * j + 2 + 3;
            int keyLength = 14 + 4 * j;
            if (dto.anchor == null || dto.anchor.Length != anchorLength || dto.keys == null || dto.keys.Length != dto.keyCount * keyLength ||
                (continuation ? dto.lockout == null || dto.lockout.Length != keyLength : dto.lockout != null && dto.lockout.Length != 0))
                throw new FormatException("The close-bar reference artifact has an unexpected layout.");

            int k = 0;
            var state = new DeadliftPreparedAscentPlan.Anchor
            {
                Root = PoseAt(dto.anchor, ref k), Bar = PoseAt(dto.anchor, ref k),
                Feet = new[] { PoseAt(dto.anchor, ref k), PoseAt(dto.anchor, ref k) },
                GripRotations = new[] { QuatAt(dto.anchor, ref k), QuatAt(dto.anchor, ref k) },
                JointIds = (string[])jointIds.Clone(),
                Measured = new Quaternion[j]
            };
            for (int i = 0; i < j; i++)
                state.Measured[i] = QuatAt(dto.anchor, ref k);
            state.StartProgress = FloatAt(dto.anchor, ref k);
            state.LiftRate = FloatAt(dto.anchor, ref k);
            state.BarTangent = new Vector3(FloatAt(dto.anchor, ref k), FloatAt(dto.anchor, ref k), FloatAt(dto.anchor, ref k));

            var plan = new Plan
            {
                State = state, MinGapM = dto.minGapM, SweptGapM = dto.sweptGapM, ClosureM = dto.closureM, ClosureDeg = dto.closureDeg
            };
            k = 0;
            for (int n = 0; n < dto.keyCount; n++)
            {
                Pose root = PoseAt(dto.keys, ref k), bar = PoseAt(dto.keys, ref k);
                var logical = new Dictionary<string, Quaternion>(StringComparer.Ordinal);
                foreach (string id in jointIds)
                    logical.Add(id, QuatAt(dto.keys, ref k));
                plan.Keys.Add((root, bar, logical));
            }
            if (continuation)
            {
                k = 0;
                Pose root = PoseAt(dto.lockout, ref k), bar = PoseAt(dto.lockout, ref k);
                var logical = new Dictionary<string, Quaternion>(StringComparer.Ordinal);
                foreach (string id in jointIds)
                    logical.Add(id, QuatAt(dto.lockout, ref k));
                plan.Lockout = new DeadliftPreparedAscentPlan.Sample { Root = root, Bar = bar, Logical = logical };
            }
            return plan;
        }

        private static PathDto Write(DeadliftLiftPath.Snapshot path)
        {
            if (path == null)
                throw new InvalidOperationException("The artifact needs the stock lift path.");
            int n = path.Keys[0].X.Length;
            var dto = new PathDto
            {
                keyCount = path.Keys.Count, parameterCount = n,
                x = new long[path.Keys.Count * n], cost = new long[path.Keys.Count], hard = new long[path.Keys.Count],
                rise = new int[path.Keys.Count], lambda = new int[path.Keys.Count], flags = new int[path.Keys.Count],
                scalars = new[] { Bits(path.PlannedLockoutRise), Bits(path.ScheduleLockoutRise), Bits(path.HomotopyTorso0), Bits(path.HomotopyHip0), path.BarProximity ? 1 : 0 }
            };
            for (int i = 0; i < path.Keys.Count; i++)
            {
                var k = path.Keys[i];
                if (k.X.Length != n)
                    throw new InvalidOperationException("Stock path keys differ in parameter count.");
                for (int j = 0; j < n; j++)
                    dto.x[i * n + j] = BitConverter.DoubleToInt64Bits(k.X[j]);
                dto.cost[i] = BitConverter.DoubleToInt64Bits(k.Cost);
                dto.hard[i] = BitConverter.DoubleToInt64Bits(k.Hard);
                dto.rise[i] = Bits(k.Rise);
                dto.lambda[i] = Bits(k.Lambda);
                dto.flags[i] = (k.EvaluatedAsLockout ? 1 : 0) | (k.Lockout ? 2 : 0) | (k.FreeRise ? 4 : 0);
            }
            return dto;
        }

        private static DeadliftLiftPath.Snapshot Read(PathDto dto)
        {
            if (dto == null || dto.keyCount < 2 || dto.x == null || dto.x.Length != dto.keyCount * dto.parameterCount ||
                dto.cost?.Length != dto.keyCount || dto.hard?.Length != dto.keyCount || dto.rise?.Length != dto.keyCount ||
                dto.lambda?.Length != dto.keyCount || dto.flags?.Length != dto.keyCount || dto.scalars?.Length != 5)
                throw new FormatException("The close-bar reference artifact has no valid stock lift path.");
            var s = new DeadliftLiftPath.Snapshot
            {
                PlannedLockoutRise = FromBits(dto.scalars[0]), ScheduleLockoutRise = FromBits(dto.scalars[1]),
                HomotopyTorso0 = FromBits(dto.scalars[2]), HomotopyHip0 = FromBits(dto.scalars[3]), BarProximity = dto.scalars[4] != 0
            };
            int n = dto.parameterCount;
            for (int i = 0; i < dto.keyCount; i++)
            {
                var x = new double[n];
                for (int j = 0; j < n; j++)
                    x[j] = BitConverter.Int64BitsToDouble(dto.x[i * n + j]);
                s.Keys.Add((x, FromBits(dto.rise[i]), (dto.flags[i] & 1) != 0, (dto.flags[i] & 2) != 0,
                    BitConverter.Int64BitsToDouble(dto.cost[i]), BitConverter.Int64BitsToDouble(dto.hard[i]),
                    FromBits(dto.lambda[i]), (dto.flags[i] & 4) != 0));
            }
            return s;
        }

        private static int Bits(float v) => BitConverter.ToInt32(BitConverter.GetBytes(v), 0);
        private static float FromBits(int v) => BitConverter.ToSingle(BitConverter.GetBytes(v), 0);
        private static void Put(List<int> o, float v) => o.Add(Bits(v));
        private static void Put(List<int> o, Vector3 v) { Put(o, v.x); Put(o, v.y); Put(o, v.z); }
        private static void Put(List<int> o, Quaternion q) { Put(o, q.x); Put(o, q.y); Put(o, q.z); Put(o, q.w); }
        private static void Put(List<int> o, Pose p) { Put(o, p.position); Put(o, p.rotation); }
        private static float FloatAt(int[] a, ref int k) => FromBits(a[k++]);
        private static Quaternion QuatAt(int[] a, ref int k) => new Quaternion(FloatAt(a, ref k), FloatAt(a, ref k), FloatAt(a, ref k), FloatAt(a, ref k));
        private static Pose PoseAt(int[] a, ref int k)
        {
            var position = new Vector3(FloatAt(a, ref k), FloatAt(a, ref k), FloatAt(a, ref k));
            return new Pose(position, QuatAt(a, ref k));
        }
    }
}
